export const getHanjaByLevel = (level) => {
  const levelsOrder = HANJA_LEVELS;
  const targetIndex = levelsOrder.indexOf(level);
  if (targetIndex === -1) return [];
  
  let cumulativeData = [];
  for (let i = 0; i <= targetIndex; i++) {
    const lvlName = levelsOrder[i];
    cumulativeData = [...cumulativeData, ...(HANJA_RAW_DATA[lvlName] || [])];
  }
  return cumulativeData;
};

export const getRandomHanjaList = (level, count) => {
  const list = [...getHanjaByLevel(level)];
  return list.sort(() => 0.5 - Math.random()).slice(0, count);
};
